	"fmt"
	"os"
)

const MOD int64 = 998244353

func mod(x int64) int64 {
	x %= MOD
	if x < 0 {
		x += MOD
	}
	return x
}

func mul(a, b int64) int64 {
	return (a * b) % MOD
}

func getPrimes(n int) []bool {
	isPrime := make([]bool, n+1)
	primes := make([]int, 0)

	for i := 2; i <= n; i++ {
		if !isPrime[i] {
			isPrime[i] = true
			primes = append(primes, i)
		}
		for _, p := range primes {
			if p > n/i {
				break
			}
			isPrime[p*i] = false
			if i%p == 0 {
				break
			}
		}
	}

	return isPrime
}

func solve(n int, m int64) int64 {
	pre := int64(1)
	M := mod(m)
	res := int64(0)
	ans := M
	ans1 := M
	primes := getPrimes(n + 10)

	for i := 2; i <= n; i++ {
